{
  "candidate_edge_types": [
    {
      "name": "DISAMBIGUATES_AMBIGUOUS_OBSERVATION",
      "definition": "A subsequent extraction or visualization action is taken to resolve uncertainty about the correct interpretation of an earlier observation.",
      "source_description": "An earlier observation that is ambiguous or inconsistent and requires further interpretation.",
      "target_description": "A subsequent action that re-examines, re-crops, re-renders, or otherwise inspects the same content to determine its correct interpretation."
    },
    {
      "name": "VALIDATES_CANDIDATES_AGAINST_EXPECTED_OUTCOME",
      "definition": "An agent action tests multiple candidate interpretations or solutions against a known expected outcome or success constraint in order to identify the correct one.",
      "source_description": "A known expected result or success criterion from the task specification.",
      "target_description": "A testing action or script that evaluates candidate interpretations against that expected result to select the correct one."
    },
    {
      "name": "PIVOTS_TO_ALTERNATIVE_STRATEGY_AFTER_REPEATED_AMBIGUITY",
      "definition": "After one approach repeatedly produces ambiguous or unreliable results, the agent adopts a different strategy that does not rely on that approach.",
      "source_description": "A series of ambiguous or unreliable observations produced by an initial method.",
      "target_description": "A subsequent action or script that implements an alternative strategy to accomplish the task."
    },
    {
      "name": "VERIFIES_PRODUCED_ARTIFACT",
      "definition": "A subsequent inspection action checks the content or correctness of an artifact produced by an earlier action.",
      "source_description": "An earlier action that produced an output artifact or result.",
      "target_description": "A subsequent action that reads, inspects, or otherwise verifies the produced artifact."
    },
    {
      "name": "COMPLETES_TASK_AFTER_VERIFICATION",
      "definition": "The agent finalizes the task after a produced result or artifact has been verified as satisfying the task requirement.",
      "source_description": "A verified result or output that meets the required success condition.",
      "target_description": "A task completion action that ends execution or triggers grading."
    },
    {
      "name": "USES_PREVIOUS_RESOURCE_AS_INPUT",
      "definition": "A subsequent operation consumes a previously discovered or retrieved resource, such as a file path or file content, as input.",
      "source_description": "A previously discovered or retrieved resource, file, or value.",
      "target_description": "A subsequent action or script that uses that resource as an input."
    },
    {
      "name": "PRODUCES_OUTPUT_ON_SUCCESSFUL_CANDIDATE_MATCH",
      "definition": "An agent action produces the required output artifact when a candidate interpretation satisfies the expected validation criterion.",
      "source_description": "A candidate interpretation or solution that satisfies the expected validation criterion.",
      "target_description": "The required output artifact produced as a result."
    }
  ]
}

